// Rotas.tsx
import { Route, Routes } from 'react-router-dom'
import Home from './pages/Home'  // Página inicial
import ProductPage from './pages/ProductPage'  // Página do produto (onde o modal deve abrir)

type RotasProps = {
  openModal: () => void
  closeModal: () => void
}

const Rotas = ({ openModal, closeModal }: RotasProps) => {
  return (
    <Routes>
      <Route path="/" element={<Home />} /> {/* Página principal */}
      <Route
        path="/produto/:id"
        element={<ProductPage openModal={openModal} closeModal={closeModal} />}
      /> {/* Página do produto onde o modal será aberto */}
    </Routes>
  )
}

export default Rotas
